(()=>{const x=new OffscreenCanvas(200,50).getContext('2d');x.font='16px Arial';const out={};for(const cp of [0,1,9,10,31,127,128,152,159,160,888,65533,1114111]){const text=String.fromCodePoint(cp),m=x.measureText(text);out[cp]={width:m.width}}out.after=x.measureText('Normal text').width;for(const family of ['Segoe UI','Segoe UI Symbol','Segoe UI Emoji','Times New Roman','Arial']){x.font='16px "'+family+'"';out[family]={replacement:x.measureText('\ufffd').width,del:x.measureText('\u007f').width}}return out})()
